<?php declare(strict_types=1);use FastWebsite\Core\View;?>
<section class="admin-page-heading"><div><p class="eyebrow">Website content</p><h1>Pages and announcements</h1><p>Build reusable pages and time-sensitive notices.</p></div><div class="table-actions"><a class="button button-secondary" href="<?=View::escape($baseUrl)?>admin/pages/announcements/create">New announcement</a><a class="button button-primary" href="<?=View::escape($baseUrl)?>admin/pages/create">New page</a></div></section><section class="admin-card"><h2>Pages</h2><div class="table-wrap"><table><thead><tr><th>Page</th><th>Navigation</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php if($pages===[]):?><tr><td colspan="4">No pages yet.</td></tr><?php endif;?><?php foreach($pages as$p):?><tr><td><strong><?=View::escape($p['title'])?></strong><br><small>/<?=View::escape($p['slug'])?></small></td><td><?=$p['show_in_navigation']?'Shown':'Hidden'?></td><td><?=View::escape($p['status'])?></td><td><div class="table-actions"><a href="<?=View::escape($baseUrl)?>admin/pages/<?=(int)$p['id']?>/edit">Edit</a><?php $a=$p['status']==='published'?'archive':($p['status']==='archived'?'restore':'publish');?><form method="post" action="<?=View::escape($baseUrl)?>admin/pages/<?=(int)$p['id']?>/workflow"><input type="hidden" name="_token" value="<?=View::escape($csrfToken)?>"><button class="link-button" name="action" value="<?=$a?>"><?=ucfirst($a)?></button></form></div></td></tr><?php endforeach;?></tbody></table></div></section><section class="admin-card" id="announcements"><h2>Announcements</h2><div class="table-wrap"><table><thead><tr><th>Notice</th><th>Window</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php if($announcements===[]):?><tr><td colspan="4">No announcements yet.</td></tr><?php endif;?><?php foreach($announcements as$n):?><tr><td><strong><?=View::escape($n['title'])?></strong><br><small><?=View::escape($n['announcement_type'])?></small></td><td><?=View::escape($n['starts_at']??'Immediately')?> – <?=View::escape($n['ends_at']??'No end')?></td><td><?=View::escape($n['status'])?></td><td><div class="table-actions"><a href="<?=View::escape($baseUrl)?>admin/pages/announcements/<?=(int)$n['id']?>/edit">Edit</a><?php $a=$n['status']==='published'?'archive':($n['status']==='archived'?'restore':'publish');?><form method="post" action="<?=View::escape($baseUrl)?>admin/pages/announcements/<?=(int)$n['id']?>/workflow"><input type="hidden" name="_token" value="<?=View::escape($csrfToken)?>"><button class="link-button" name="action" value="<?=$a?>"><?=ucfirst($a)?></button></form></div></td></tr><?php endforeach;?></tbody></table></div></section>
